cypress_script:
describe('Buttons Page Tests', () => {
  it('should click the Click Me button and verify URL remains the same', () => {
    cy.visit('https://demoqa.com/buttons');
    cy.get('button#sp5Bi').click();
    cy.url().should('eq', 'https://demoqa.com/buttons');
  });

  it('should double-click the Double Click Me button and verify URL remains the same', () => {
    cy.visit('https://demoqa.com/buttons');
    cy.get('button#doubleClickBtn').dblclick();
    cy.url().should('eq', 'https://demoqa.com/buttons');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Buttons Page Tests', () => {
  test('should click the Click Me button and verify URL remains the same', async ({ page }) => {
    await page.goto('https://demoqa.com/buttons');
    await page.click('button#sp5Bi');
    expect(page.url()).toBe('https://demoqa.com/buttons');
  });

  test('should double-click the Double Click Me button and verify URL remains the same', async ({ page }) => {
    await page.goto('https://demoqa.com/buttons');
    await page.dblclick('button#doubleClickBtn');
    expect(page.url()).toBe('https://demoqa.com/buttons');
  });
});
